#include <iostream>
#include <vector>
using namespace std;

int main() {
    // Definizione del vettore di numeri
    vector<int> numeri = {15, 23, 36, 42, 58, 77, 91, 14, 35, 29};

    // Variabile per calcolare la somma
    int somma = 0;

    // Sommiamo tutti gli elementi del vettore
    for(const auto& num : numeri) {
        somma += num;
    }

    // Calcoliamo la media
    double media = static_cast<double>(somma) / numeri.size();

    // Stampa della media
    cout << "La media dei valori nel vettore e': " << media << endl << endl;
    system("pause");
}
